// One rich card per installation — the sole in-app explainer for the ADR 0020
// gate. Avatar · login · type/status badges (Active / Suspended / Hidden) · meta
// strip (repo access · plan/seat · role) · per-state body (suspended note ·
// blocked explainer+CTAs · seat panel) · actions.

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  AlertTriangle,
  Building2,
  CheckCircle2,
  Circle,
  Clock,
  ExternalLink,
  Eye,
  Folder,
  Loader2,
  Lock,
  ShieldCheck,
  SlidersHorizontal,
  Tag,
  User,
  Users,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Collapse, CollapseChevron } from '@/components/ui/collapse';
import {
  fetchInstallationRepos,
  toRepoStats,
  type InstallationRepoStats,
} from '../../../github/client';
import { openExternalUrl } from '../../../desktop/openExternal';
import { canManageBilling, daysLeft } from '../../../billing/entitlement';
import { OrgPlanActions, type GateReason } from '../../../billing/OrgPlanActions';
import { TrialCountdown } from '../../../billing/TrialCountdown';
import { AccountAvatar } from './AccountAvatar';
import { SeatPanel } from './SeatPanel';
import type { InstalledAccount } from './useOrgAccess';

function RepoAccessStat({
  selection,
  stats,
  refreshing = false,
}: {
  selection: 'all' | 'selected';
  stats?: InstallationRepoStats;
  refreshing?: boolean;
}) {
  if (!stats) return <Skeleton className="h-3.5 w-40" />;
  const priv = !stats.capped ? <> · {stats.private} private</> : null;
  return (
    <span className="inline-flex items-center gap-1.5 text-muted-foreground">
      <Folder className="size-3.5 text-muted-foreground" />
      {selection === 'all' ? (
        <span>
          <span className="font-medium text-foreground">All repositories</span> ·{' '}
          {stats.total} repos{priv}
        </span>
      ) : (
        <span>
          <span className="font-medium text-foreground">{stats.total} selected</span>
          {priv}
        </span>
      )}
      {refreshing && (
        <Loader2 className="size-3 animate-spin text-muted-foreground" />
      )}
    </span>
  );
}

// Per-org plan badge (ADR 0020). free (personal) · Pro / Trial (seated, with the
// trial countdown) · No plan (blocked — calm outline, NOT red) · Checking plan…
// (entitlement resolving — never flash "No plan"). Org-wide seat usage lives in
// the SeatPanel (it has the claimant data); here we show the viewer's own seat.
function PlanStat({ acct }: { acct: InstalledAccount }) {
  const plan = acct.plan;
  if (plan.tier === 'unknown') return null;
  if (plan.tier === 'loading') {
    return (
      <span className="inline-flex items-center gap-1.5 text-muted-foreground">
        <Loader2 className="size-3.5 animate-spin" />
        <span>Checking plan…</span>
      </span>
    );
  }
  if (plan.tier === 'free') {
    return (
      <span className="inline-flex items-center gap-1.5 text-muted-foreground">
        <Tag className="size-3.5 text-muted-foreground" />
        <span>
          <span className="font-medium text-foreground">Free</span> · personal plan
        </span>
      </span>
    );
  }
  if (plan.tier === 'blocked') {
    return (
      <Badge variant="outline" className="gap-1 !text-muted-foreground">
        <Circle className="size-2.5 fill-muted-foreground/40 text-muted-foreground/40" />
        No plan
      </Badge>
    );
  }
  if (plan.tier === 'seats-full') {
    return (
      <Badge variant="outline" className="gap-1 !text-muted-foreground">
        <Users className="size-3" />
        Seats full
      </Badge>
    );
  }
  const { seat } = plan;
  const trialing = seat.status === 'trialing';
  const left = daysLeft(seat);
  return (
    <span className="inline-flex items-center gap-2 text-muted-foreground">
      {trialing ? (
        <span className="inline-flex items-center gap-1 rounded-md border border-amber-300/60 bg-amber-50 px-2 py-0.5 text-[11px] font-semibold text-amber-700 dark:border-amber-700/50 dark:bg-amber-900/30 dark:text-amber-300">
          <Clock className="size-3" /> Trial
        </span>
      ) : (
        <Badge variant="secondary" className="gap-1">
          <ShieldCheck className="size-3" /> Pro
        </Badge>
      )}
      {trialing && left != null && <TrialCountdown daysLeft={left} />}
      <span className="font-mono text-[11px] tabular-nums text-muted-foreground">
        your seat #{seat.index}
      </span>
    </span>
  );
}

// Title-row status chip. Suspended (GitHub state) and Hidden (blocked — its real
// user-facing effect) take precedence over Active.
function StatusPill({ state }: { state: 'active' | 'suspended' | 'hidden' }) {
  if (state === 'suspended') {
    return (
      <span className="inline-flex items-center gap-1 rounded-full border border-pyor-warn/30 bg-pyor-warn/10 px-2 py-[2px] text-[11px] font-medium text-pyor-warn">
        <AlertTriangle className="size-3" /> Suspended
      </span>
    );
  }
  if (state === 'hidden') {
    return (
      <span className="inline-flex items-center gap-1 rounded-full border border-border bg-muted px-2 py-[2px] text-[11px] font-medium text-muted-foreground">
        <Eye className="size-3" /> Hidden
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1 rounded-full border border-pyor-pass/30 bg-pyor-pass/10 px-2 py-[2px] text-[11px] font-medium text-pyor-pass">
      <CheckCircle2 className="size-3" /> Active
    </span>
  );
}

// Gated-org explainer (ADR 0020) — sole in-app explanation + role CTAs. Calm
// neutral surface (the org isn't broken; it just needs a plan, or a free seat).
function GatedCardBody({
  acct,
  reason,
}: {
  acct: InstalledAccount;
  reason: GateReason;
}) {
  const canBill = acct.role === 'owner' || acct.role === 'admin';
  const personalNote = canBill ? '' : ' Your personal account keeps working as normal.';
  return (
    <div className="mt-3 rounded-lg border border-border bg-muted/40 p-3.5">
      <div className="flex items-start gap-2.5">
        <div className="flex size-7 shrink-0 items-center justify-center rounded-md bg-background text-muted-foreground ring-1 ring-border">
          <Lock className="size-3.5" />
        </div>
        <div className="min-w-0 flex-1">
          <p className="text-[12.5px] leading-relaxed text-muted-foreground">
            {reason === 'seats-full' ? (
              <>
                <span className="font-medium text-foreground">{acct.account.login}</span>{' '}
                is on a paid plan, but all its seats are in use — so its pull requests
                stay hidden for you until a seat frees up.{personalNote}
              </>
            ) : (
              <>
                <span className="font-medium text-foreground">{acct.account.login}</span>{' '}
                needs a plan before Pyor can read its pull requests. Until then, its
                PRs and notifications stay hidden across the app.{personalNote}
              </>
            )}
          </p>
          <div className="mt-3">
            <OrgPlanActions
              githubOrgId={acct.account.id}
              login={acct.account.login}
              role={acct.role}
              reason={reason}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

export function InstalledAccountCard({ acct }: { acct: InstalledAccount }) {
  const repos = useQuery({
    queryKey: ['installation-repos', acct.id],
    queryFn: () => fetchInstallationRepos(acct.id),
    select: toRepoStats,
    placeholderData: (prev) => prev,
    staleTime: 5 * 60_000,
  });
  const reposRefreshing = repos.isFetching && !repos.isPending;

  const isOrg = acct.account.type === 'Organization';
  const seated = acct.plan.tier === 'pro';
  // Seat management is owner/admin-only — members can't add/revoke seats, so the
  // "Manage seats" control is hidden for them (their own seat # still shows in
  // PlanStat). Matches canManageBilling gating used in SeatPanel/checkout.
  const canManageSeats = seated && canManageBilling(acct.role);
  const gated = acct.plan.tier === 'blocked' || acct.plan.tier === 'seats-full';
  const gateReason: GateReason =
    acct.plan.tier === 'seats-full' ? 'seats-full' : 'no-plan';
  const [seatOpen, setSeatOpen] = useState(false);
  const roleLabel =
    acct.role === 'owner' ? 'Owner' : acct.role === 'admin' ? 'Admin' : 'Member';
  const status: 'active' | 'suspended' | 'hidden' = acct.suspended
    ? 'suspended'
    : gated
      ? 'hidden'
      : 'active';

  return (
    <Card className={acct.suspended ? 'border-pyor-warn/50' : ''}>
      <div className="flex items-start gap-3 p-4">
        <AccountAvatar
          login={acct.account.login}
          type={acct.account.type}
          avatarUrl={acct.account.avatarUrl}
          size={40}
        />
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="truncate text-[14px] font-semibold tracking-tight text-foreground">
              {acct.account.login}
            </span>
            <Badge variant="outline" className="gap-1">
              {isOrg ? (
                <Building2 className="size-3 text-muted-foreground" />
              ) : (
                <User className="size-3 text-muted-foreground" />
              )}
              {isOrg ? 'Organization' : 'Personal'}
            </Badge>
            <StatusPill state={status} />
            <button
              title="Open on GitHub"
              onClick={() => openExternalUrl(acct.account.htmlUrl)}
              className="ml-auto inline-flex size-7 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground"
            >
              <ExternalLink className="size-3.5" />
            </button>
          </div>

          <div className="mt-2.5 flex flex-wrap items-center gap-x-5 gap-y-2 text-[12px]">
            <RepoAccessStat
              selection={acct.repositorySelection}
              stats={repos.data}
              refreshing={reposRefreshing}
            />
            <PlanStat acct={acct} />
            <span className="inline-flex items-center gap-1.5 text-muted-foreground">
              <ShieldCheck className="size-3.5 text-muted-foreground" />
              <span>
                You're <span className="font-medium text-foreground">{roleLabel}</span>
              </span>
            </span>
          </div>

          {acct.suspended && (
            <div className="mt-3 flex items-start gap-2 rounded-md border border-pyor-warn/30 bg-pyor-warn/10 px-2.5 py-2 text-[12px] text-pyor-warn">
              <AlertTriangle className="mt-px size-3.5 shrink-0" />
              <span>
                Suspended on GitHub — Pyor can't read these repositories until the
                installation is re-enabled.
              </span>
            </div>
          )}

          {gated && <GatedCardBody acct={acct} reason={gateReason} />}

          {canManageSeats && acct.plan.tier === 'pro' && (
            <Collapse open={seatOpen}>
              <SeatPanel
                githubOrgId={acct.account.id}
                seat={acct.plan.seat}
                role={acct.role}
              />
            </Collapse>
          )}

          <div className="mt-3 flex flex-wrap items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => openExternalUrl(acct.htmlUrl)}
            >
              {acct.suspended ? (
                <>
                  <ExternalLink className="size-3.5" /> Re-enable on GitHub
                </>
              ) : (
                <>
                  <SlidersHorizontal className="size-3.5" /> Configure repos
                </>
              )}
            </Button>
            {canManageSeats && (
              <button
                onClick={() => setSeatOpen((o) => !o)}
                className="inline-flex h-8 items-center gap-1.5 rounded-md px-2.5 text-[12px] font-medium text-muted-foreground hover:bg-muted hover:text-foreground"
              >
                <Users className="size-3.5 text-muted-foreground" />
                {seatOpen ? 'Hide seats' : 'Manage seats'}
                <CollapseChevron
                  open={seatOpen}
                  className="size-3.5 text-muted-foreground"
                />
              </button>
            )}
          </div>
        </div>
      </div>
    </Card>
  );
}
