// Settings → Organizations & repository access.
//
// Replaces the single minimal "Organizations" row. Pyor reads PRs only from
// accounts where its GitHub App is installed — this section is the home for
// "manage where Pyor can see my repositories." Adaptive warning (strong banner
// when nothing is installed, quiet hint otherwise) + a rich card per installed
// account. Adding more orgs goes through GitHub's own install picker (the
// footer CTA): a GitHub-App user token can't enumerate orgs it isn't installed
// on, so we can't list "orgs you're not installed on" ourselves.

import {
  AlertTriangle,
  CheckCircle2,
  ExternalLink,
  Info,
  KeyRound,
  Plus,
  XCircle,
} from 'lucide-react';
import type { ReactNode } from 'react';
import { useNavigate } from '@tanstack/react-router';
import { Button } from '@/components/ui/button';
import { FetchingBar } from '@/components/ui/fetching-bar';
import { GithubMark } from '../../../auth/GithubMark';
import { Card } from '@/components/ui/card';
import { Separator } from '@/components/ui/separator';
import { Skeleton } from '@/components/ui/skeleton';
import { openExternalUrl } from '../../../desktop/openExternal';
import { APP_INSTALL_URL } from '../../../github/appInstall';
import { useOrgAccess } from './useOrgAccess';
import { InstalledAccountCard } from './InstalledAccountCard';

const APP_DESCRIPTION =
  'Pyor reads pull requests only from accounts where its GitHub App is installed — not every org you belong to. Each organization needs a plan; your personal account is always free.';

function SectionHeader({
  description = APP_DESCRIPTION,
  refreshing = false,
}: {
  description?: string;
  refreshing?: boolean;
}) {
  return (
    <div>
      <h2 className="text-[15px] font-semibold tracking-tight text-foreground">
        Organizations &amp; repository access
      </h2>
      <p className="mt-1 max-w-[64ch] text-[13px] text-muted-foreground">
        {description}
      </p>
      {/* Background refetch in flight — the prior list stays put, so a thin
          pulsing bar signals it's updating (matches the Pulls list). Always
          rendered so toggling it never shifts layout. */}
      <FetchingBar active={refreshing} className="mt-3 w-full rounded-full" />
    </div>
  );
}

// Personal access tokens have no installation model — repo access follows the
// token's scopes. Explain that instead of erroring on /user/installations.
function PatAccessNote() {
  const navigate = useNavigate();
  return (
    <Card className="p-4">
      <div className="flex items-start gap-3">
        <div className="flex size-9 shrink-0 items-center justify-center rounded-full bg-muted text-muted-foreground">
          <KeyRound className="size-[18px]" />
        </div>
        <div className="min-w-0 flex-1 space-y-3">
          <p className="text-[13px] leading-relaxed text-muted-foreground">
            Repository access is controlled by your token's scopes on GitHub, not
            by per-account installs — so there's nothing to install or manage
            here. Adjust which repositories and organizations Pyor can read from
            your token settings.
          </p>
          <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() =>
                openExternalUrl('https://github.com/settings/tokens')
              }
            >
              <ExternalLink className="size-3.5" /> Manage token on GitHub
            </Button>
            <button
              type="button"
              onClick={() => void navigate({ to: '/welcome' })}
              className="text-[12px] text-primary hover:underline"
            >
              Or sign in with the Pyor GitHub App for org seats &amp; per-repo
              control
            </button>
          </div>
        </div>
      </div>
    </Card>
  );
}

function ZeroInstallBanner() {
  return (
    <div className="rounded-lg border border-pyor-warn/40 bg-pyor-warn/10 p-4 shadow-sm">
      <div className="flex items-start gap-3">
        <div className="flex size-9 shrink-0 items-center justify-center rounded-full bg-pyor-warn/15 text-pyor-warn">
          <AlertTriangle className="size-5" />
        </div>
        <div className="min-w-0 flex-1">
          <h3 className="text-[13.5px] font-semibold text-foreground">
            You can only see public repositories right now
          </h3>
          <p className="mt-1 max-w-[58ch] text-[12.5px] leading-relaxed text-muted-foreground">
            Pyor isn't installed on any account yet, so private pull requests stay
            invisible. Install its GitHub App on your personal account or an
            organization to start reviewing private PRs.
          </p>
          <div className="mt-3">
            <Button size="sm" onClick={() => openExternalUrl(APP_INSTALL_URL)}>
              <GithubMark className="size-3.5" /> Install on GitHub
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

function QuietHint({ count }: { count: number }) {
  return (
    <div className="flex items-start gap-2 px-1 text-[12px] text-muted-foreground">
      <Info className="mt-px size-3.5 shrink-0 text-muted-foreground" />
      <span>
        Pyor reads repositories from{' '}
        {count === 1 ? 'this account' : `these ${count} accounts`} only. Private
        repos on any other org stay hidden until you install Pyor there too.
      </span>
    </div>
  );
}

function GroupLabel({
  icon: Icon,
  tone = 'muted',
  children,
}: {
  icon: typeof CheckCircle2;
  tone?: 'muted' | 'pass';
  children: ReactNode;
}) {
  return (
    <div className="flex items-center gap-1.5 px-1 text-[10.5px] font-semibold uppercase tracking-wider text-muted-foreground">
      <Icon
        className={`size-3.5 ${tone === 'pass' ? 'text-pyor-pass' : 'text-muted-foreground'}`}
      />
      {children}
    </div>
  );
}

export function OrganizationsSection() {
  const { method, isLoading, isRefreshing, isError, installed, refetch } =
    useOrgAccess();

  if (method === 'pat') {
    return (
      <section className="mb-6 space-y-4">
        <SectionHeader description="You're signed in with a personal access token, so Pyor's repository access follows your token's scopes — across every organization. There are no GitHub App installations to manage here." />
        <PatAccessNote />
      </section>
    );
  }

  if (isLoading) {
    return (
      <section className="mb-6 space-y-3">
        <SectionHeader />
        <Skeleton className="h-24 w-full rounded-lg" />
        <Skeleton className="h-24 w-full rounded-lg" />
      </section>
    );
  }

  if (isError) {
    return (
      <section className="mb-6 space-y-3">
        <SectionHeader />
        <Card className="flex items-center gap-3 p-4 text-[13px] text-muted-foreground">
          <XCircle className="size-4 text-destructive" />
          <span className="flex-1">Couldn't load your installations.</span>
          <Button variant="outline" size="sm" onClick={refetch}>
            Retry
          </Button>
        </Card>
      </section>
    );
  }

  return (
    <section className="mb-6 space-y-6">
      <SectionHeader refreshing={isRefreshing} />

      {installed.length === 0 && <ZeroInstallBanner />}

      {installed.length > 0 && (
        <div className="space-y-3">
          <GroupLabel icon={CheckCircle2} tone="pass">
            Installed · {installed.length}
          </GroupLabel>
          <div className="space-y-3">
            {installed.map((a) => (
              <InstalledAccountCard key={a.id} acct={a} />
            ))}
          </div>
        </div>
      )}

      {installed.length > 0 && <QuietHint count={installed.length} />}

      {/* Primary "add an org" path. We can't list a user's non-installed orgs
          (a GitHub-App token only sees installed ones), so the install picker —
          GitHub's own UI, which DOES show all your accounts — is how you widen
          access. */}
      <Separator />
      <div className="flex items-center justify-between gap-4 rounded-lg border bg-muted/30 p-4">
        <div className="min-w-0">
          <div className="text-[13px] font-medium text-foreground">
            Add an account or organization
          </div>
          <div className="mt-0.5 max-w-[52ch] text-[12px] leading-relaxed text-muted-foreground">
            Pyor only reads accounts where its GitHub App is installed. Install it
            on another personal account or organization to review their pull
            requests too — you'll pick the account on GitHub.
          </div>
        </div>
        <Button
          size="sm"
          className="shrink-0"
          onClick={() => openExternalUrl(APP_INSTALL_URL)}
        >
          <Plus className="size-3.5" /> Install on GitHub
        </Button>
      </div>
    </section>
  );
}
