// Auth-method badge — glanceable PAT vs GitHub App marker in the Account card.
// PAT = neutral (a credential you manage); App = emerald "pass" green (a
// verified Pyor session). The colour contrast is the whole point: you should
// tell the two apart without reading the label.

import { KeyRound } from 'lucide-react';
import { GithubMark } from '../../../auth/GithubMark';
import type { AuthMethod } from '../../../auth/tokenStore';

export function AuthMethodBadge({ method }: { method: AuthMethod }) {
  if (method === 'github-app') {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full border border-pyor-pass/30 bg-pyor-pass/10 px-2.5 py-1 text-[11.5px] font-semibold text-pyor-pass">
        <GithubMark className="size-3.5" />
        GitHub App
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full border border-border bg-muted px-2.5 py-1 text-[11.5px] font-semibold text-foreground">
      <KeyRound className="size-3.5" />
      Personal access token
    </span>
  );
}
