// Seat panel for a seated org (ADR 0020 #7) — usage (X of N) + the claimant
// list + revoke that Polar can't show (Polar owns quantity & invoices; OUR
// backend owns who occupies the seats). Admins see every claimant and can
// revoke a passive member's seat; members see only their own seat. Falls back to
// the entitlement's seat counts when no billing backend is wired (mock).

import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import {
  ExternalLink,
  Loader2,
  ShieldCheck,
  Users,
  XCircle,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { ConfirmModal } from '../../../pr/lifecycle/ConfirmModal';
import { canManageBilling, useBillingAction } from '../../../billing/entitlement';
import {
  useSeatClaimants,
  useRevokeSeat,
  type SeatClaimant,
} from '../../../billing/seats';
import type { OrgRole, SeatAssignment } from '../../../auth/oauthBroker';
import { AccountAvatar } from './AccountAvatar';

function claimedLabel(ms: number | null): string {
  if (!ms) return 'seat held';
  return `Claimed since ${new Date(ms).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}`;
}

function UsageHeader({ used, total }: { used: number; total: number }) {
  const full = used >= total;
  const near = total > 0 && used / total >= 0.9;
  const pct = total > 0 ? Math.min(100, Math.round((used / total) * 100)) : 0;
  return (
    <div className="flex items-center gap-3 border-b border-border px-3.5 py-3">
      <Users className="size-4 shrink-0 text-muted-foreground" />
      <div className="min-w-0 flex-1">
        <div className="flex items-center justify-between gap-2">
          <span className="text-[12.5px] font-semibold text-foreground">Team seats</span>
          <span className="font-mono text-[11.5px] tabular-nums text-muted-foreground">
            <span className={full ? 'text-amber-600 dark:text-amber-400' : 'text-foreground'}>
              {used}
            </span>{' '}
            of {total} used
          </span>
        </div>
        <div className="mt-1.5 h-1.5 w-full overflow-hidden rounded-full bg-muted">
          <div
            className={`h-full rounded-full ${near ? 'bg-amber-500' : 'bg-foreground'}`}
            style={{ width: `${pct}%` }}
          />
        </div>
      </div>
    </div>
  );
}

function SeatRow({
  claimant,
  isYou,
  busy,
  onRevoke,
}: {
  claimant: SeatClaimant;
  isYou: boolean;
  busy: boolean;
  onRevoke: () => void;
}) {
  return (
    <div className="group flex items-center gap-2.5 px-3.5 py-2">
      <AccountAvatar login={claimant.login} type="User" size={24} />
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1.5">
          <span className="truncate text-[12.5px] font-medium text-foreground">
            {claimant.login}
          </span>
          {isYou && (
            <span className="rounded bg-secondary px-1.5 py-0 text-[9.5px] font-semibold text-secondary-foreground">
              You
            </span>
          )}
        </div>
        <div className="text-[11px] text-muted-foreground">{claimedLabel(claimant.claimedAt)}</div>
      </div>
      {busy ? (
        <span className="inline-flex h-7 items-center gap-1.5 px-2 text-[11.5px] text-muted-foreground">
          <Loader2 className="size-3.5 animate-spin" /> Revoking…
        </span>
      ) : isYou ? (
        <span className="px-2 text-[11px] text-muted-foreground/40">—</span>
      ) : (
        <button
          onClick={onRevoke}
          className="inline-flex h-7 items-center gap-1.5 rounded-md px-2 text-[11.5px] font-medium text-muted-foreground opacity-0 transition hover:bg-destructive/10 hover:text-destructive focus:opacity-100 group-hover:opacity-100"
        >
          <XCircle className="size-3.5" /> Revoke
        </button>
      )}
    </div>
  );
}

function RowsSkeleton() {
  return (
    <div className="divide-y divide-border/60">
      {[0, 1, 2].map((i) => (
        <div key={i} className="flex items-center gap-2.5 px-3.5 py-2.5">
          <span className="size-6 shrink-0 animate-pulse rounded-full bg-muted" />
          <div className="flex-1 space-y-1.5">
            <span className="block h-2.5 w-28 animate-pulse rounded bg-muted" />
            <span className="block h-2 w-20 animate-pulse rounded bg-muted/60" />
          </div>
        </div>
      ))}
    </div>
  );
}

export function SeatPanel({
  githubOrgId,
  seat,
  role,
}: {
  githubOrgId: number;
  seat: SeatAssignment;
  role: OrgRole;
}) {
  const canBill = canManageBilling(role);
  const queryClient = useQueryClient();
  const viewerLogin = queryClient.getQueryData<{ login: string }>(['viewer'])?.login;
  const claimants = useSeatClaimants(githubOrgId, canBill);
  const revoke = useRevokeSeat(githubOrgId);
  const billing = useBillingAction();
  const [target, setTarget] = useState<SeatClaimant | null>(null);

  const rows = claimants.data ?? [];
  // Org usage = claimed seats from the backend. Fall back to the viewer's own
  // seat index ONLY when the claimant list is genuinely absent (no billing
  // backend wired / query failed) — never when the backend explicitly returns
  // an empty list, which must read as 0 used, not as the viewer's index.
  const used = claimants.data ? rows.length : seat.index;

  return (
    <div className="mt-3 overflow-hidden rounded-lg border border-border bg-muted/30">
      <UsageHeader used={used} total={seat.total} />

      {!canBill ? (
        <div className="flex items-start gap-2.5 px-3.5 py-3 text-[12px] text-muted-foreground">
          <ShieldCheck className="mt-px size-3.5 shrink-0 text-muted-foreground" />
          <span>
            You hold{' '}
            <span className="font-medium text-foreground">
              seat {seat.index} of {seat.total}
            </span>
            . Seats are managed by an admin — nothing for you to do here.
          </span>
        </div>
      ) : claimants.isPending ? (
        <RowsSkeleton />
      ) : (
        <>
          <div
            className={`divide-y divide-border/60 ${rows.length > 7 ? 'max-h-[208px] overflow-y-auto' : ''}`}
          >
            {rows.map((c) => (
              <SeatRow
                key={c.seatId}
                claimant={c}
                isYou={!!viewerLogin && c.login.toLowerCase() === viewerLogin.toLowerCase()}
                busy={revoke.isPending && target?.seatId === c.seatId}
                onRevoke={() => setTarget(c)}
              />
            ))}
            {rows.length <= 1 && (
              <div className="px-3.5 py-3 text-[12px] text-muted-foreground">
                {seat.total - used > 0 ? (
                  <>
                    You're the only one on a seat so far. As teammates open Pyor
                    on{' '}
                    <span className="font-medium text-foreground">{seat.login}</span>
                    , they'll claim the remaining {seat.total - used} seat
                    {seat.total - used === 1 ? '' : 's'}.
                  </>
                ) : (
                  <>
                    All {seat.total} seat{seat.total === 1 ? '' : 's'} on{' '}
                    <span className="font-medium text-foreground">{seat.login}</span>{' '}
                    {seat.total === 1 ? 'is' : 'are'} in use. Add seats in billing
                    to give teammates access.
                  </>
                )}
              </div>
            )}
          </div>
          <div className="flex items-center justify-between gap-2 border-t border-border bg-background/40 px-3.5 py-2.5">
            <span className="text-[11.5px] text-muted-foreground">
              Billed per seat. Add or remove seats in{' '}
              <span className="font-medium text-foreground/80">billing</span>.
            </span>
            <Button
              variant="ghost"
              size="sm"
              className="h-7"
              disabled={billing.pending}
              onClick={() => billing.manageSeats(githubOrgId)}
            >
              {billing.pending ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : (
                <ExternalLink className="size-3.5" />
              )}{' '}
              Manage billing
            </Button>
          </div>
        </>
      )}

      <ConfirmModal
        open={!!target}
        onOpenChange={(o) => !o && setTarget(null)}
        title={`Revoke ${target?.login ?? ''}'s seat?`}
        description={`This frees a seat for another member. ${target?.login ?? 'They'} loses access to ${seat.login} until they re-claim one. Your bill (${seat.total} seats) is unchanged.`}
        confirmLabel="Revoke seat"
        confirmIcon={XCircle}
        pending={revoke.isPending}
        onConfirm={() =>
          target && revoke.mutate(target.seatId, { onSuccess: () => setTarget(null) })
        }
      />
    </div>
  );
}
