// Advanced model override per provider. Shows a generic "Default model"
// option plus a short curated list; the list is populated from the
// provider's LIVE models endpoint when a key is configured (ADR 0026 — do
// not hard-code version strings in UI), falling back to a static seed.

import { useQuery } from '@tanstack/react-query';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import type { AiProvider } from './aiSettings';
import { getAiKey } from './aiKeyStore';
import { makeAdapter, FALLBACK_MODELS } from '../provider';

const DEFAULT_OPTION = '__default__';

export function AiModelSelect({
  provider,
  value,
  onChange,
}: {
  provider: AiProvider;
  /** '' = provider default. */
  value: string;
  onChange: (next: string) => void;
}) {
  const hasKey = !!getAiKey(provider);
  const models = useQuery({
    // The `v2` segment invalidates any list persisted by the previous
    // (alphabetical, first-8) curation so the corrected newest-first list
    // shows on the next load instead of a stale cached one. Refetch on mount
    // + a short stale window so newly-released models surface promptly.
    queryKey: ['ai-models', 'v2', provider, hasKey],
    queryFn: async () => {
      const key = getAiKey(provider);
      if (!key) return FALLBACK_MODELS[provider];
      return makeAdapter(provider, key).listModels();
    },
    staleTime: 5 * 60_000,
    refetchOnMount: true,
    enabled: hasKey,
  });
  const options = models.data ?? FALLBACK_MODELS[provider];

  return (
    <Select
      value={value || DEFAULT_OPTION}
      onValueChange={(v) => onChange(v === DEFAULT_OPTION ? '' : v)}
    >
      <SelectTrigger className="h-8 min-w-[220px] text-[12.5px]">
        <SelectValue placeholder="Default model" />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value={DEFAULT_OPTION}>Default model</SelectItem>
        {options.map((m) => (
          <SelectItem key={m.id} value={m.id}>
            {m.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}
