// ── Diff typography (font size + line height) ───────────────────
//
// A self-contained card driven by the same `usePrefs` store as the
// other diff settings. Two range sliders mirrored by ± steppers, a
// row of preset chips for the canonical sizes, and a reset link.
//
// The chip set comes from DIFF_TYPOGRAPHY_PRESETS so the catalogue
// lives next to the storage layer — adding a "Huge" preset only
// touches one file.

function DiffTypographySection() {
  const { prefs, setPrefs } = usePrefs();
  const matchedPreset = DIFF_TYPOGRAPHY_PRESETS.find(
    (p) => p.fontSize === prefs.fontSize && p.lineHeight === prefs.lineHeight,
  );
  const isAtDefault =
    prefs.fontSize === DEFAULT_PREFS.fontSize &&
    prefs.lineHeight === DEFAULT_PREFS.lineHeight;
  const lhRatio = (prefs.lineHeight / prefs.fontSize).toFixed(2);
  return (
    <section className="mb-6">
      <Card>
        <CardHeader>
          <CardTitle>Font size &amp; line height</CardTitle>
          <CardDescription>
            Affects monospace code rendering in the diff pane only. Comment
            threads and the rest of the UI are unchanged.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-5 pb-5">
          {/* Font size */}
          <div>
            <div className="mb-1.5 flex items-baseline">
              <span className="text-[13px] font-medium text-foreground">
                Font size
              </span>
              <span className="ml-auto font-mono text-[11.5px] tabular-nums text-muted-foreground">
                {prefs.fontSize}px
              </span>
            </div>
            <div className="flex items-center gap-3">
              <span
                aria-hidden
                className="select-none font-mono text-[10px] text-muted-foreground/70"
              >
                A
              </span>
              <input
                type="range"
                min={FONT_SIZE_MIN}
                max={FONT_SIZE_MAX}
                step={1}
                value={prefs.fontSize}
                aria-label="Font size"
                onChange={(e) =>
                  setPrefs({ fontSize: Number(e.target.value) })
                }
                className="flex-1 accent-primary"
              />
              <span
                aria-hidden
                className="select-none font-mono text-[14px] text-muted-foreground/70"
              >
                A
              </span>
              <Stepper
                value={prefs.fontSize}
                min={FONT_SIZE_MIN}
                max={FONT_SIZE_MAX}
                onChange={(v) => setPrefs({ fontSize: v })}
                label="font size"
              />
            </div>
          </div>

          {/* Line height */}
          <div>
            <div className="mb-1.5 flex items-baseline">
              <span className="text-[13px] font-medium text-foreground">
                Line height
              </span>
              <span className="ml-auto font-mono text-[11.5px] tabular-nums text-muted-foreground">
                {prefs.lineHeight}px · {lhRatio}×
              </span>
            </div>
            <div className="flex items-center gap-3">
              <Rows3
                aria-hidden
                size={14}
                className="text-muted-foreground/70"
              />
              <input
                type="range"
                min={LINE_HEIGHT_MIN}
                max={LINE_HEIGHT_MAX}
                step={1}
                value={prefs.lineHeight}
                aria-label="Line height"
                onChange={(e) =>
                  setPrefs({ lineHeight: Number(e.target.value) })
                }
                className="flex-1 accent-primary"
              />
              <Rows3
                aria-hidden
                size={16}
                className="text-muted-foreground/70"
              />
              <Stepper
                value={prefs.lineHeight}
                min={LINE_HEIGHT_MIN}
                max={LINE_HEIGHT_MAX}
                onChange={(v) => setPrefs({ lineHeight: v })}
                label="line height"
              />
            </div>
          </div>

          {/* Presets */}
          <div>
            <div className="mb-1.5 text-[13px] font-medium text-foreground">
              Presets
            </div>
            <div className="flex flex-wrap gap-1.5">
              {DIFF_TYPOGRAPHY_PRESETS.map((p) => {
                const active = matchedPreset?.id === p.id;
                return (
                  <button
                    key={p.id}
                    type="button"
                    aria-pressed={active}
                    onClick={() =>
                      setPrefs({
                        fontSize: p.fontSize,
                        lineHeight: p.lineHeight,
                      })
                    }
                    className={`inline-flex items-center gap-1.5 rounded-md border px-2.5 py-1 text-[12px] transition-colors ${
                      active
                        ? 'border-foreground bg-foreground text-background'
                        : 'border-border bg-card text-foreground hover:border-border/80 hover:bg-muted/60'
                    }`}
                  >
                    <span className="font-medium">{p.label}</span>
                    <span
                      className={`font-mono text-[10.5px] tabular-nums ${
                        active
                          ? 'text-background/70'
                          : 'text-muted-foreground'
                      }`}
                    >
                      {p.fontSize}/{p.lineHeight}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Reset row */}
          <div className="flex items-center gap-2 border-t border-border/60 pt-3 text-[12px] text-muted-foreground">
            <Info size={13} strokeWidth={1.75} />
            <span>
              Changes apply immediately. Reset restores{' '}
              {DEFAULT_PREFS.fontSize}px / {DEFAULT_PREFS.lineHeight}px.
            </span>
            <Button
              variant="ghost"
              size="xs"
              className="ml-auto px-2 text-[12px]"
              disabled={isAtDefault}
              onClick={() =>
                setPrefs({
                  fontSize: DEFAULT_PREFS.fontSize,
                  lineHeight: DEFAULT_PREFS.lineHeight,
                })
              }
            >
              Reset to defaults
            </Button>
          </div>
        </CardContent>
      </Card>
    </section>
  );
}

function Stepper({
  value,
  min,
  max,
  onChange,
  label,
}: {
  value: number;
  min: number;
  max: number;
  onChange: (v: number) => void;
  label: string;
}) {
  return (
    <div className="flex items-center rounded-md border border-border bg-card">
      <button
        type="button"
        aria-label={`Decrease ${label}`}
        disabled={value <= min}
        onClick={() => onChange(Math.max(min, value - 1))}
        className="flex size-7 items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-40 disabled:hover:text-muted-foreground"
      >
        <Minus size={14} strokeWidth={1.75} />
      </button>
      <span className="w-9 border-x border-border py-1 text-center font-mono text-[11.5px] tabular-nums">
        {value}
      </span>
      <button
        type="button"
        aria-label={`Increase ${label}`}
        disabled={value >= max}
        onClick={() => onChange(Math.min(max, value + 1))}
        className="flex size-7 items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-40 disabled:hover:text-muted-foreground"
      >
        <Plus size={14} strokeWidth={1.75} />
      </button>
    </div>
  );
}

// ── Appearance ──────────────────────────────────────────────────

type ThemeChoice = 'system' | 'light' | 'dark';

function AppearanceSection() {
  // Pyor's existing theme state is binary (light/dark) — system-follow
  // isn't wired yet. We expose all three swatches per the design; the
  // System option is presented but disabled (with a hint that it's
  // coming) until the ThemeProvider gains an "auto" mode.
  const { dark, setDark } = useTheme();
  const active: ThemeChoice = dark ? 'dark' : 'light';
  const onSelect = (c: ThemeChoice) => {
    if (c === 'light') setDark(false);
    if (c === 'dark') setDark(true);
    // 'system' is a no-op for now.
  };
  return (
    <SettingsSection
      id="appearance"
      title="Appearance"
      description={
        <>
          Light or dark window chrome.{' '}
          <kbd className="rounded-[3px] border border-border bg-card px-1 py-px text-[11px] text-muted-foreground [font-family:inherit]">
            ⌘⇧T
          </kbd>{' '}
          toggles from anywhere.
        </>
      }
    >
      <SettingsRow
        label="Theme"
        hint="Applies to the window chrome and the diff renderer."
        layout="stack"
      >
        <ThemeRadioGroup active={active} onSelect={onSelect} />
      </SettingsRow>
    </SettingsSection>
  );
}

// ── Privacy section (ADR 0021) ──────────────────────────────────
//
// The product runs PostHog under legitimate interest with this opt-out. The
// switch IS the kill switch: flipping it off calls setAnalyticsOptOut, which
// halts capture immediately and persists across reloads. Hidden entirely when
// analytics isn't configured (dev/mock), so there's no dead control. Error
// tracking (Sentry) is intentionally not toggled here — it runs on a
// stability/security basis, not analytics consent.

// ── About / Updates (desktop only) ──────────────────────────────
// Renders nothing on the web build. Shows the installed version and a
// manual "Check for updates" button. The actual outcome surfaces as a
// toast: on silent-auto-update platforms via the update-downloaded
// event; on notifier platforms (macOS / .deb) the main process fires
// the "Download" toast when one exists, so here we only report the
// "up to date" / "checking" cases (ADR 0023).
function AboutSection() {
  const version = useQuery({
    queryKey: ['app-version'],
    queryFn: () => bridge()!.appVersion(),
    enabled: isElectron(),
    // The running version is constant per process, but it CHANGES across a
    // self-update (new binary, new process). The query is persisted to
    // IndexedDB, so a plain staleTime:Infinity would restore + show the old
    // version forever. Always refetch on mount so Settings reflects the
    // actually-running build. (Also excluded from persistence in main.tsx.)
    staleTime: Infinity,
    refetchOnMount: 'always',
  });
  const check = useMutation({
    mutationFn: () => bridge()!.checkForUpdates(),
    onSuccess: (res) => {
      const msg =
        res.channel === 'auto'
          ? 'Checking for updates — you’ll be notified if one is ready.'
          : res.available
            ? null // the "Download" toast is fired by the main process
            : 'You’re on the latest version.';
      if (msg) toast.message(msg);
    },
    onError: () => toast.error('Couldn’t check for updates. Try again.'),
  });
  const update = useUpdateState();

  if (!isElectron()) return null;

  // While a background update is in flight, the row reflects its lifecycle
  // (download → install → ready) instead of the manual check button — the same
  // state the sidebar UpdateGauge shows. The button only returns once idle.
  const restart = () => {
    const b = bridge();
    if (!b || update.kind !== 'ready') return;
    void (update.via === 'staged' ? b.applyUpdate() : b.quitAndInstall());
  };

  return (
    <SettingsSection
      id="about"
      title="About"
      description="The installed build and update channel for the desktop app."
    >
      <SettingsRow label="Version" hint="The version of Pyor running on this device.">
        <span className="font-mono text-[12.5px] text-muted-foreground">
          {version.data ?? '…'}
        </span>
      </SettingsRow>
      <SettingsRow
        label="Updates"
        hint={
          update.kind === 'ready'
            ? 'A new version is downloaded and ready to apply.'
            : update.kind === 'idle'
              ? 'Check the release channel for a newer version.'
              : 'A new version is downloading in the background.'
        }
      >
        {update.kind === 'idle' ? (
          <Button
            variant="outline"
            size="sm"
            onClick={() => check.mutate()}
            disabled={check.isPending}
          >
            {check.isPending ? 'Checking…' : 'Check for updates'}
          </Button>
        ) : update.kind === 'ready' ? (
          <Button size="sm" onClick={restart}>
            <Check className="size-3.5" />
            Restart to update
          </Button>
        ) : (
          <span className="flex items-center gap-2 text-[12.5px] text-muted-foreground">
            {update.kind === 'download' ? (
              <>
                <ArrowDownToLine className="size-3.5" />
                <span className="tabular-nums">Downloading… {update.percent}%</span>
              </>
            ) : (
              <>
                <Loader2 className="size-3.5 animate-spin" />
                Installing…
              </>
            )}
          </span>
        )}
      </SettingsRow>
    </SettingsSection>
  );
}

function PrivacySection() {
  const optedOut = useSyncExternalStore(subscribeOptOut, getOptOutSnapshot);
  if (!analyticsConfigured) return null;

  const onToggle = (enabled: boolean) => {
    // When opting OUT, record the final event before capture stops; when
    // opting back IN, enable first so the event is captured.
    if (!enabled) {
      track(Events.AnalyticsOptoutToggled, { opted_out: true });
      setAnalyticsOptOut(true);
      return;
    }
    setAnalyticsOptOut(false);
    track(Events.AnalyticsOptoutToggled, { opted_out: false });
  };

  return (
    <SettingsSection
      id="privacy"
      title="Privacy"
      description="Pyor runs on as little data as possible. Your code, diffs and comments never leave your machine."
    >
      <SettingsRow
        label="Usage analytics"
        align="start"
        hint={
          <>
            Anonymous-by-default product analytics that help us see which
            features get used — never your code or comment text. Turn this off
            and we stop collecting them. Crash diagnostics still run so we can
            fix bugs.
          </>
        }
      >
        <Switch
          checked={!optedOut}
          onCheckedChange={onToggle}
          aria-label="Usage analytics"
        />
      </SettingsRow>
      {/* Turn a lonely toggle into a trust statement: exactly what's collected
       * vs what never leaves this Mac. */}
      <PrivacyDataSplit />
    </SettingsSection>
  );
}

function PrivacyDataSplit() {
  return (
    <div className="px-5 pb-4 pt-3.5">
      <div className="grid grid-cols-2 gap-2.5">
        <DataList
          kind="collect"
          items={['App version & OS', 'Crash stack traces', 'Feature usage counts']}
        />
        <DataList
          kind="never"
          items={['Source code or diffs', 'PR titles or comments', 'Tokens or repo names']}
        />
      </div>
    </div>
  );
}

function DataList({
  kind,
  items,
}: {
  kind: 'collect' | 'never';
  items: string[];
}) {
  const isCollect = kind === 'collect';
  return (
    <div className="rounded-lg border border-border/60 bg-muted/30 px-3 py-2.5">
      <div className="mb-1.5 flex items-center gap-1.5">
        {isCollect ? (
          <CheckCircle2 className="size-3.5 text-pyor-pass" strokeWidth={2} />
        ) : (
          <XCircle className="size-3.5 text-muted-foreground" strokeWidth={2} />
        )}
        <span className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
          {isCollect ? 'We collect' : 'Never'}
        </span>
      </div>
      <div className="flex flex-col gap-1">
        {items.map((it) => (
          <span key={it} className="text-[11.5px] leading-snug text-muted-foreground">
            {it}
          </span>
        ))}
      </div>
    </div>
  );
}

function ThemeRadioGroup({
  active,
  onSelect,
}: {
  active: ThemeChoice;
  onSelect: (c: ThemeChoice) => void;
}) {
  const options: { id: ThemeChoice; label: string; desc: string; disabled?: boolean }[] = [
    { id: 'system', label: 'System', desc: 'Coming soon', disabled: true },
    { id: 'light', label: 'Light', desc: 'Always light' },
    { id: 'dark', label: 'Dark', desc: 'Always dark' },
  ];
  return (
    <div className="grid w-full max-w-[560px] grid-cols-3 gap-2.5">
      {options.map((o) => (
        <ThemeSwatchCard
          key={o.id}
          label={o.label}
          desc={o.desc}
          kind={o.id}
          active={active === o.id}
          disabled={o.disabled}
          onSelect={() => !o.disabled && onSelect(o.id)}
        />
      ))}
    </div>
  );
}

function ThemeSwatchCard({
  label,
  desc,
  kind,
  active,
  disabled,
  onSelect,
}: {
  label: string;
  desc: string;
  kind: ThemeChoice;
  active: boolean;
  disabled?: boolean;
  onSelect: () => void;
}) {
  // The selected ring uses `ring-2 ring-primary/20` so it survives the
  // dark-mode flip without re-computing rgba alpha tuples — the legacy
  // version branched on `T.isDark` for that exact reason.
  return (
    <button
      type="button"
      onClick={onSelect}
      disabled={disabled}
      aria-pressed={active}
      className={`relative flex cursor-pointer flex-col gap-1.5 rounded-lg border bg-card p-2 text-left font-sans disabled:cursor-not-allowed disabled:opacity-55 ${
        active
          ? 'border-primary ring-2 ring-primary/20'
          : 'border-border/60'
      }`}
    >
      <SwatchPreview kind={kind} />
      <div className="flex items-center gap-1.5 px-0.5">
        <span
          className={`inline-flex size-3 shrink-0 items-center justify-center rounded-full border-[1.5px] bg-card ${
            active ? 'border-primary' : 'border-border'
          }`}
        >
          {active && (
            <span className="size-1.5 rounded-full bg-primary" />
          )}
        </span>
        <span className="text-[12.5px] font-semibold text-foreground">
          {label}
        </span>
      </div>
      <span className="px-0.5 text-[11px] text-muted-foreground">{desc}</span>
    </button>
  );
}

function SwatchPreview({ kind }: { kind: ThemeChoice }) {
  if (kind === 'system') {
    // Split: light on the left, dark on the right.
    return (
      <div className="flex h-16 overflow-hidden rounded-[5px] border border-border/60">
        <SwatchHalf dark={false} />
        <SwatchHalf dark={true} />
      </div>
    );
  }
  return (
    <div className="h-16 overflow-hidden rounded-[5px] border border-border/60">
      <SwatchHalf dark={kind === 'dark'} />
    </div>
  );
}

function SwatchHalf({ dark }: { dark: boolean }) {
  // These hex values aren't theme tokens — they're a fixed
  // visual representation of the macOS window chrome used in
  // both light and dark previews regardless of the active app
  // theme. Tailwind arbitrary-value classes keep them out of
  // inline styles per ADR 0011.
  return (
    <div
      className={`flex h-full flex-1 flex-col ${
        dark ? 'bg-[#1f1f22]' : 'bg-[#ffffff]'
      }`}
    >
      <div
        className={`flex h-2.5 items-center gap-[3px] border-b px-1 ${
          dark
            ? 'border-b-[#3a3a3e] bg-[#2a2a2e]'
            : 'border-b-[#d8d8dc] bg-[#ececec]'
        }`}
      >
        <span className="size-1 rounded-full bg-[#ff5f57]" />
        <span className="size-1 rounded-full bg-[#febc2e]" />
        <span className="size-1 rounded-full bg-[#28c840]" />
      </div>
      <div className="flex flex-1">
        <div
          className={`w-3.5 border-r ${
            dark
              ? 'border-r-[#2e2e32] bg-[#202023]'
              : 'border-r-[#ebebef] bg-[#f1f1f4]'
          }`}
        />
        <div className="flex flex-1 flex-col gap-0.5 p-1">
          <div
            className={`h-0.5 w-[60%] rounded-sm ${
              dark ? 'bg-[#3a3a3e]' : 'bg-[#d8d8dc]'
            }`}
          />
          <div
            className={`h-0.5 w-[40%] rounded-sm ${
              dark ? 'bg-[#2e2e32]' : 'bg-[#e0e0e4]'
            }`}
          />
          <div
            className={`h-0.5 w-[70%] rounded-sm ${
              dark ? 'bg-[#2e2e32]' : 'bg-[#e0e0e4]'
            }`}
          />
        </div>
      </div>
    </div>
  );
}

// ── Screen shell ─────────────────────────────────────────────────

export function SettingsScreen({
  onBack: onBackProp,
  onSignedOut: onSignedOutProp,
  fluid = false,
  width = 1320,
  height = 820,
}: Props) {
  const navigate = useNavigate();
  const onBack =
    onBackProp ??
    (() => void navigate({ to: '/inbox', search: INBOX_DEFAULTS }));
  const onSignedOut =
    onSignedOutProp ?? (() => void navigate({ to: '/welcome' }));
  return (
    <PyorWindow
      width={width}
      height={height}
      title="Settings"
      subtitle="Preferences are stored on this device"
      fluid={fluid}
      toolbar={
        <Button variant="outline" size="sm" onClick={onBack}>
          <ChevronLeft />
          Back
        </Button>
      }
      status={
        <>
          <span className="inline-flex items-center gap-1.5">
            <span className="size-1.5 rounded-full bg-pyor-pass" />
            Saved locally · no sync
          </span>
          <span className="mx-3 text-border">│</span>
          <span className="font-mono text-[11px]">
            localStorage / IndexedDB
          </span>
          <span className="flex-1" />
          <span className="mr-2">
            <kbd className="rounded-[3px] border border-border bg-card px-1 py-px text-[10.5px] text-muted-foreground [font-family:inherit]">
              ⌘⇧T
            </kbd>{' '}
            toggle theme
          </span>
        </>
      }
    >
      <div className="flex-1 overflow-auto bg-panel">
        <div className="mx-auto max-w-[760px] px-9 pt-7 pb-[60px]">
          <AccountSection onSignedOut={onSignedOut} />
          <OrganizationsSection />
          <ApiUsageSection />
          <DiffPrefsSection />
          <DiffTypographySection />
          <AppearanceSection />
          <PrivacySection />
          <AiSettingsSection />
          <AboutSection />
        </div>
      </div>
    </PyorWindow>
  );
}
