// First-enable disclosure (ADR 0026 / design spec). AI activates only after
// the user acknowledges that triggering an AI action sends the PR's diff +
// changed files to the provider they configure. Also re-opened by the
// "What AI can see" link.

import { ShieldCheck } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { AiButton, AiMark } from '../aikit';

export function AiDisclosureDialog({
  open,
  onOpenChange,
  mode = 'enable',
  onConfirm,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** 'enable' = first-enable required ack; 'info' = re-opened from the link. */
  mode?: 'enable' | 'info';
  onConfirm: () => void;
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[460px]">
        <DialogHeader className="items-center text-center">
          <span className="mb-3 inline-flex size-12 items-center justify-center rounded-2xl bg-violet-100 text-violet-600">
            <AiMark className="size-6" />
          </span>
          <DialogTitle className="text-[16px]">
            {mode === 'enable' ? 'Turn on AI assistance?' : 'What AI can see'}
          </DialogTitle>
          <DialogDescription className="text-[12.5px] leading-relaxed">
            When you trigger an AI action, Pyor sends the relevant PR code — the diff and changed
            files — to the AI provider you configure. Nothing is sent until you press a button, and
            nothing is posted to GitHub.
          </DialogDescription>
        </DialogHeader>

        <div className="mt-1 rounded-lg border border-border bg-muted/50 p-3 text-left">
          <div className="flex items-start gap-2 text-[12px] text-muted-foreground">
            <ShieldCheck className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
            <span>
              This is the one disclosed exception to “your code never leaves your machine.” Your
              provider key is kept in your system keychain (or this browser on web) — never in the
              synced preferences file.
            </span>
          </div>
        </div>

        <div className="mt-5 flex justify-end gap-2">
          {mode === 'enable' ? (
            <>
              <Button variant="ghost" size="sm" onClick={() => onOpenChange(false)}>
                Cancel
              </Button>
              <AiButton variant="solid" size="sm" mark onClick={onConfirm}>
                Enable AI assistance
              </AiButton>
            </>
          ) : (
            <Button variant="default" size="sm" onClick={() => onOpenChange(false)}>
              Got it
            </Button>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}
