// Review-guidelines editor (ADR 0026 / design spec). Markdown textarea +
// Write/Preview tabs + a starter template. Framed as "add your review
// preferences" on top of Pyor's built-in reviewer — optional, works empty.
// Shapes inline hints only (grouping stays mechanical).

import { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Plus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { AiMark } from '../aikit';

const STARTER = `## My review preferences
- Prefer native / library solutions over custom code; flag reinvented wheels.
- Simplify. Call out needless abstraction and premature generalization.
- Avoid useEffect for derived state; prefer useMemo / computed values.
- Watch for antipatterns: effects with missing deps, unstable callbacks.

## What I care most about
- Correctness at boundaries (off-by-one, empty, max).
- Public API / contract changes — these need extra scrutiny.
- Tests that actually exercise the new branch.

## Tone for drafted comments
- Direct, specific, kind. Lead with the concrete issue, then the suggestion.`;

function wordCount(s: string): number {
  return s.trim() ? s.trim().split(/\s+/).length : 0;
}

export function AiGuidelinesEditor({
  value,
  onSave,
}: {
  value: string;
  onSave: (next: string) => void;
}) {
  const [draft, setDraft] = useState(value);
  const [tab, setTab] = useState<'write' | 'preview'>('write');
  const dirty = draft !== value;
  const empty = draft.trim().length === 0;

  return (
    <div className="overflow-hidden rounded-lg border border-border bg-background">
      <div className="flex items-center gap-2 border-b border-border/60 bg-muted/40 px-2 py-1.5">
        <Tabs value={tab} onValueChange={(v) => setTab(v as 'write' | 'preview')}>
          <TabsList indicator="pill" className="h-7">
            <TabsTrigger
              value="write"
              className="h-6 text-[11.5px] data-[state=active]:bg-transparent data-[state=active]:shadow-none"
            >
              Write
            </TabsTrigger>
            <TabsTrigger
              value="preview"
              className="h-6 text-[11.5px] data-[state=active]:bg-transparent data-[state=active]:shadow-none"
            >
              Preview
            </TabsTrigger>
          </TabsList>
        </Tabs>
        <span className="ml-1 text-[11px] text-muted-foreground">Markdown</span>
        <div className="ml-auto flex items-center gap-1.5">
          <AiMark className="size-3 text-violet-500" />
          <span className="text-[11px] text-violet-600">Shapes your inline hints</span>
        </div>
      </div>

      {tab === 'preview' ? (
        <div className="ai-md max-h-[260px] min-h-[180px] overflow-auto px-4 py-3 text-[12.5px] leading-relaxed text-foreground">
          {empty ? (
            <p className="text-muted-foreground">Nothing to preview yet.</p>
          ) : (
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{draft}</ReactMarkdown>
          )}
        </div>
      ) : (
        <div className="relative">
          <textarea
            rows={11}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Add your review preferences — e.g. “prefer native solutions, simplify, avoid useEffect for derived state. Lead drafted comments with the concrete issue.”  Markdown supported. Optional — Pyor’s built-in reviewer works without it."
            className="w-full resize-none bg-transparent px-4 py-3 font-mono text-[12px] leading-relaxed text-foreground outline-none placeholder:text-muted-foreground"
          />
          {empty && (
            <div className="px-4 pb-3">
              <button
                type="button"
                onClick={() => setDraft(STARTER)}
                className="inline-flex items-center gap-1.5 rounded-md border border-violet-200 bg-violet-50 px-2 py-1 text-[11px] font-medium text-violet-700 hover:bg-violet-100"
              >
                <Plus className="size-3" />
                Start from a template
              </button>
            </div>
          )}
        </div>
      )}

      <div className="flex items-center gap-2 border-t border-border/60 bg-muted/40 px-3 py-2">
        <span className="text-[11px] text-muted-foreground">
          {empty ? 'Optional — adds to Pyor’s built-in reviewer.' : `Saved locally · ${wordCount(value)} words`}
        </span>
        <div className="ml-auto flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={() => setDraft(value)} disabled={!dirty}>
            Reset
          </Button>
          <Button variant="default" size="sm" onClick={() => onSave(draft)} disabled={!dirty}>
            Save preferences
          </Button>
        </div>
      </div>
    </div>
  );
}
