// Account avatar — square hashed monogram tile for ORGS, round photo for USERS.
// The shape distinction reads as "org vs personal" at a glance (per the design).

import { useState } from 'react';

// Decorative hashed tile colors (white text on top works in light + dark).
const TILE_BG = [
  'bg-indigo-500',
  'bg-emerald-600',
  'bg-rose-500',
  'bg-sky-600',
  'bg-violet-500',
  'bg-amber-500',
];

const hash = (s: string): number =>
  s.split('').reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 0);

export function AccountAvatar({
  login,
  type,
  avatarUrl,
  size = 40,
}: {
  login: string;
  type: 'User' | 'Organization';
  avatarUrl?: string;
  size?: number;
}) {
  const [imgFailed, setImgFailed] = useState(false);

  if (type === 'Organization') {
    const bg = TILE_BG[hash(login) % TILE_BG.length];
    const letter = (login.replace(/[^a-z0-9]/gi, '').charAt(0) || '?').toUpperCase();
    return (
      <div
        className={`inline-flex shrink-0 items-center justify-center rounded-md font-semibold text-white ring-1 ring-black/10 ${bg}`}
        style={{ width: size, height: size, fontSize: Math.round(size * 0.42) }}
      >
        {letter}
      </div>
    );
  }

  // A User always has a public GitHub avatar at github.com/{login}.png, so fall
  // back to that when an explicit URL isn't supplied (e.g. seat claimants, whose
  // billing record carries only a login — not an avatar). onError still drops to
  // initials if even that 404s. size*2 keeps it crisp on retina.
  const photoSrc = avatarUrl ?? `https://github.com/${login}.png?size=${size * 2}`;
  if (photoSrc && !imgFailed) {
    return (
      <img
        src={photoSrc}
        alt={login}
        onError={() => setImgFailed(true)}
        className="shrink-0 rounded-full bg-muted object-cover ring-1 ring-border"
        style={{ width: size, height: size }}
      />
    );
  }

  const initials = login
    .split(/[-\s]/)
    .map((s) => s[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();
  return (
    <div
      className="inline-flex shrink-0 items-center justify-center rounded-full bg-muted font-medium text-foreground ring-1 ring-border"
      style={{ width: size, height: size, fontSize: Math.round(size * 0.34) }}
    >
      {initials}
    </div>
  );
}
