// One provider-key row (ADR 0026 / design spec). Masked, paste-friendly
// input with reveal + clear, a Test affordance, a neutral connection-state
// chip, and the spend-limit nudge. Per-row copy is provider-neutral — the
// Active-provider control decides which one runs.

import { useState } from 'react';
import {
  AlertTriangle,
  CheckCircle2,
  Clock,
  Eye,
  EyeOff,
  Gauge,
  KeyRound,
  ServerCrash,
  X,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { cn } from '@/lib/utils';
import type { AiProvider } from './aiSettings';
import { getAiKey, setAiKey, clearAiKey } from './aiKeyStore';
import { ProviderIcon } from './aiProviderGuides';
import { makeAdapter } from '../provider';
import { AiError } from '../provider/types';

export type AiKeyStatus = 'untested' | 'valid' | 'invalid' | 'rate-limited' | 'error';

const SPEND_URL: Record<AiProvider, string> = {
  anthropic: 'https://console.anthropic.com/settings/limits',
  openai: 'https://platform.openai.com/settings/organization/limits',
};

const PROVIDER_LABEL: Record<AiProvider, string> = {
  anthropic: 'Anthropic',
  openai: 'OpenAI',
};

function StatusChip({ status, wait }: { status: AiKeyStatus; wait?: string }) {
  const map: Record<AiKeyStatus, { text: string; cls: string; icon?: typeof CheckCircle2; dot?: string }> = {
    untested: { text: 'Not tested', cls: 'text-muted-foreground', dot: 'bg-muted-foreground/40' },
    valid: { text: 'Connected', cls: 'text-emerald-600', icon: CheckCircle2 },
    invalid: { text: 'Key rejected', cls: 'text-amber-700', icon: AlertTriangle },
    'rate-limited': { text: 'Rate-limited', cls: 'text-amber-700', icon: Clock },
    error: { text: 'Provider error', cls: 'text-amber-700', icon: ServerCrash },
  };
  const s = map[status];
  const Icon = s.icon;
  return (
    <span className={cn('inline-flex items-center gap-1.5 text-[11.5px] font-medium', s.cls)}>
      {Icon ? (
        <Icon className="size-3.5" />
      ) : (
        <span className={cn('size-1.5 rounded-full', s.dot)} />
      )}
      {s.text}
      {status === 'rate-limited' && wait ? ` · retry in ${wait}` : ''}
    </span>
  );
}

export function AiProviderKeyRow({
  provider,
  model,
  baseUrl,
  last = false,
}: {
  provider: AiProvider;
  /** The user's model override for this provider (for the Test call). */
  model?: string;
  /** OpenAI-compatible base URL override, so Test hits the right endpoint. */
  baseUrl?: string;
  last?: boolean;
}) {
  const label = PROVIDER_LABEL[provider];
  const stored = getAiKey(provider);
  const [draft, setDraft] = useState('');
  const [editing, setEditing] = useState(!stored);
  const [revealed, setRevealed] = useState(false);
  const [status, setStatus] = useState<AiKeyStatus>(stored ? 'untested' : 'untested');
  const [wait, setWait] = useState<string | undefined>();
  const [testing, setTesting] = useState(false);

  const hasKey = !!stored && !editing;

  const masked = (k: string) =>
    k.length > 12 ? `${k.slice(0, 7)}${'•'.repeat(14)}${k.slice(-4)}` : '•'.repeat(k.length);

  async function save() {
    const v = draft.trim();
    if (!v) return;
    await setAiKey(provider, v);
    setDraft('');
    setEditing(false);
    setStatus('untested');
  }

  async function test() {
    const key = getAiKey(provider);
    if (!key) return;
    setTesting(true);
    setWait(undefined);
    try {
      await makeAdapter(provider, key, model || undefined, baseUrl || undefined).testKey();
      setStatus('valid');
    } catch (err) {
      if (err instanceof AiError) {
        if (err.kind === 'invalid-key') setStatus('invalid');
        else if (err.kind === 'rate-limited') {
          setStatus('rate-limited');
          setWait(err.retryAfter ? `${err.retryAfter}s` : '~40s');
        } else setStatus('error');
      } else {
        setStatus('error');
      }
    } finally {
      setTesting(false);
    }
  }

  async function clear() {
    await clearAiKey(provider);
    setEditing(true);
    setStatus('untested');
    setRevealed(false);
  }

  return (
    <div className={cn('px-5 py-3.5', !last && 'border-b border-border/60')}>
      <div className="flex items-center gap-3">
        <div className="flex size-7 shrink-0 items-center justify-center rounded-md border border-border bg-background text-foreground">
          <ProviderIcon id={provider} className="size-4" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="text-[13px] font-semibold text-foreground">{label}</div>
          <div className="text-[11px] text-muted-foreground">
            {provider === 'anthropic' ? 'Claude models' : 'GPT models'}
          </div>
        </div>
      </div>

      <div className="mt-2 flex items-center gap-2">
        <div className="flex h-8 flex-1 items-center gap-2 rounded-md border border-input bg-background px-2.5 focus-within:border-violet-400 focus-within:ring-2 focus-within:ring-violet-200">
          <KeyRound className="size-3.5 shrink-0 text-muted-foreground" />
          {hasKey ? (
            <span className="flex-1 truncate font-mono text-[12px] text-foreground">
              {revealed ? stored : masked(stored)}
            </span>
          ) : (
            <input
              type={revealed ? 'text' : 'password'}
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') void save();
              }}
              placeholder={`Paste your ${label} API key…`}
              className="flex-1 bg-transparent font-mono text-[12px] text-foreground outline-none placeholder:font-sans placeholder:text-muted-foreground"
            />
          )}
          {(hasKey || draft) && (
            <>
              <button
                type="button"
                title={revealed ? 'Hide' : 'Reveal'}
                onClick={() => setRevealed((r) => !r)}
                className="inline-flex size-5 items-center justify-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
              >
                {revealed ? <EyeOff className="size-3.5" /> : <Eye className="size-3.5" />}
              </button>
              {hasKey && (
                <button
                  type="button"
                  title="Clear"
                  onClick={() => void clear()}
                  className="inline-flex size-5 items-center justify-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
                >
                  <X className="size-3.5" />
                </button>
              )}
            </>
          )}
        </div>
        {hasKey ? (
          <Button variant="outline" size="sm" onClick={() => void test()} disabled={testing}>
            {testing ? 'Testing…' : 'Test'}
          </Button>
        ) : (
          <Button variant="default" size="sm" onClick={() => void save()} disabled={!draft.trim()}>
            Add key
          </Button>
        )}
      </div>

      <div className="mt-2 flex items-center gap-2">
        {hasKey ? (
          <StatusChip status={status} wait={wait} />
        ) : (
          <span className="text-[11.5px] text-muted-foreground">No key set</span>
        )}
        <span className="ml-auto inline-flex items-center gap-1 text-[11px] text-muted-foreground">
          <Gauge className="size-3" />
          <a
            href={SPEND_URL[provider]}
            target="_blank"
            rel="noreferrer"
            className="font-medium text-muted-foreground underline-offset-2 hover:text-violet-700 hover:underline"
          >
            Set a spend limit on your {label} dashboard →
          </a>
        </span>
      </div>
    </div>
  );
}
