// Settings → Account card · auth-adaptive (design handoff, 2026-06).
//
// ONE card that renders either sign-in method from the data we actually have:
//   • shared identity header (avatar / name / @login · email / View on GitHub)
//   • a hairline, then a method-specific row:
//       – PAT : "OAuth scopes" → wrapping chips (0 / 1 / 8+)
//       – App : "Session" → "Renews automatically" reassurance (no countdown)
// Plan / seat / installation data is NOT here — it lives in the Organizations
// card and must never be duplicated. Loading shows skeletons; errors recover
// in place (re-auth on 401, retry on a network failure).

import type { ReactNode } from 'react';
import { useNavigate } from '@tanstack/react-router';
import { useQueryClient } from '@tanstack/react-query';
import {
  CloudOff,
  ExternalLink,
  KeyRound,
  RefreshCw,
  ShieldCheck,
  XCircle,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { GithubMark } from '../../../auth/GithubMark';
import { signOut } from '../../../auth/signOut';
import { openExternalUrl } from '../../../desktop/openExternal';
import type { Viewer } from '../../../github/types';
import { AccountAvatar } from '../orgs/AccountAvatar';
import { AuthMethodBadge } from './AuthMethodBadge';
import { ScopePills } from './ScopePills';
import { useAccount, type AccountErrorKind } from './useAccount';

// Card-internal settings row: fixed 160px label/hint column on the left,
// content fills the rest (top-aligned so wrapping chips read from the top).
// Distinct from the page-level SettingsRow, which right-aligns its control.
function AcctRow({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: ReactNode;
}) {
  return (
    <div className="flex gap-4 border-t border-border/60 px-4 py-3.5">
      <div className="w-[160px] shrink-0 pt-px">
        <div className="text-[12.5px] font-medium text-foreground">{label}</div>
        {hint && (
          <div className="mt-0.5 text-[11.5px] leading-snug text-muted-foreground">
            {hint}
          </div>
        )}
      </div>
      <div className="min-w-0 flex-1 self-start">{children}</div>
    </div>
  );
}

function IdentityHeader({ viewer, badge }: { viewer: Viewer; badge: ReactNode }) {
  return (
    <div className="flex items-start gap-3.5 p-4">
      <AccountAvatar
        login={viewer.login}
        type="User"
        avatarUrl={viewer.avatar_url}
        size={44}
      />
      <div className="min-w-0 flex-1">
        <div className="truncate text-[14px] font-semibold text-foreground">
          {viewer.name || viewer.login}
        </div>
        <div className="mt-0.5 flex items-center gap-1.5 text-[12.5px] text-muted-foreground">
          <span className="font-mono">@{viewer.login}</span>
          {viewer.email && (
            <>
              <span className="text-muted-foreground/60">·</span>
              <span className="truncate">{viewer.email}</span>
            </>
          )}
        </div>
        <button
          onClick={() => openExternalUrl(`https://github.com/${viewer.login}`)}
          className="mt-2 inline-flex items-center gap-1 text-[12px] font-medium text-muted-foreground hover:text-foreground"
        >
          <GithubMark className="size-3.5" />
          View on GitHub
          <ExternalLink className="size-3" />
        </button>
      </div>
      <div className="shrink-0 pt-0.5">{badge}</div>
    </div>
  );
}

function LoadingCard() {
  const widths = ['w-10', 'w-16', 'w-20', 'w-14'];
  return (
    <Card className="overflow-hidden">
      <div className="flex items-start gap-3.5 p-4">
        <div className="size-11 shrink-0 animate-pulse rounded-full bg-muted" />
        <div className="min-w-0 flex-1 space-y-2 pt-1">
          <div className="h-3.5 w-32 animate-pulse rounded bg-muted" />
          <div className="h-3 w-48 animate-pulse rounded bg-muted" />
        </div>
        <div className="h-6 w-36 shrink-0 animate-pulse rounded-full bg-muted" />
      </div>
      <AcctRow label="OAuth scopes" hint="Granted by this token">
        <div className="flex flex-wrap gap-1.5">
          {widths.map((w) => (
            <div
              key={w}
              className={`h-[22px] animate-pulse rounded-md bg-muted ${w}`}
            />
          ))}
        </div>
      </AcctRow>
    </Card>
  );
}

function ErrorCard({
  kind,
  onReauth,
  onPasteToken,
  onRetry,
}: {
  kind: AccountErrorKind;
  onReauth: () => void;
  onPasteToken: () => void;
  onRetry: () => void;
}) {
  const rejected = kind === 'rejected';
  return (
    <Card className="overflow-hidden">
      <div className="flex gap-3.5 p-4">
        <div className="flex size-11 shrink-0 items-center justify-center rounded-full bg-destructive/10 text-destructive">
          {rejected ? <XCircle className="size-5" /> : <CloudOff className="size-5" />}
        </div>
        <div className="min-w-0 flex-1">
          <div className="text-[14px] font-semibold text-foreground">
            {rejected ? 'GitHub rejected this token' : "Couldn't reach GitHub"}
          </div>
          <p className="mt-1 text-[12.5px] leading-relaxed text-muted-foreground">
            {rejected ? (
              <>
                Pyor couldn&rsquo;t verify your identity —{' '}
                <code className="font-mono text-[11.5px] text-foreground">
                  GET /user
                </code>{' '}
                returned 401. The token may have been revoked or expired.
              </>
            ) : (
              <>
                Pyor couldn&rsquo;t load your account from{' '}
                <code className="font-mono text-[11.5px] text-foreground">
                  GET /user
                </code>
                . Check your connection and try again.
              </>
            )}
          </p>
          <div className="mt-3 flex items-center gap-2">
            {rejected ? (
              <>
                <Button size="sm" onClick={onReauth}>
                  <KeyRound /> Re-authenticate
                </Button>
                <Button size="sm" variant="outline" onClick={onPasteToken}>
                  Paste a new token
                </Button>
              </>
            ) : (
              <Button size="sm" onClick={onRetry}>
                <RefreshCw /> Retry
              </Button>
            )}
          </div>
        </div>
      </div>
    </Card>
  );
}

export function AccountCard({ onSignedOut }: { onSignedOut: () => void }) {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { status, method, viewer, errorKind, refetch } = useAccount();

  if (status === 'error') {
    return (
      <ErrorCard
        kind={errorKind}
        onReauth={() => {
          void signOut(queryClient).then(onSignedOut);
        }}
        onPasteToken={() => void navigate({ to: '/setup' })}
        onRetry={refetch}
      />
    );
  }

  if (status === 'loading' || !viewer) return <LoadingCard />;

  return (
    <Card className="overflow-hidden">
      <IdentityHeader viewer={viewer} badge={<AuthMethodBadge method={method} />} />
      {status === 'pat' ? (
        <AcctRow
          label="OAuth scopes"
          hint="Granted by the personal access token in use."
        >
          <ScopePills scopes={viewer.scopes} />
        </AcctRow>
      ) : (
        <AcctRow label="Session" hint="How long this sign-in stays valid.">
          <div className="flex items-start gap-2">
            <ShieldCheck className="mt-px size-4 shrink-0 text-pyor-pass" />
            <div>
              <div className="text-[12.5px] font-medium text-foreground">
                Renews automatically
              </div>
              <div className="mt-0.5 text-[11.5px] leading-snug text-muted-foreground">
                Pyor holds a short-lived token and refreshes it silently in the
                background — you won&rsquo;t be signed out.
              </div>
            </div>
          </div>
        </AcctRow>
      )}
    </Card>
  );
}
