// Trial countdown pill (ADR 0020, surface #4). Calm by default, warms to amber
// in the last stretch, pulses the dot at urgent/today — never red/alarming.
// Factual labels only ("N days left" / "Ends today"), never "Last chance!".
// Shared by the Settings org card and the global trial reminder.

type TrialUrgency = 'calm' | 'soon' | 'urgent' | 'today';

function trialUrgency(daysLeft: number): TrialUrgency {
  if (daysLeft <= 0) return 'today';
  if (daysLeft <= 3) return 'urgent';
  if (daysLeft <= 7) return 'soon';
  return 'calm';
}

const TONE: Record<TrialUrgency, string> = {
  calm: 'bg-muted text-muted-foreground border-border',
  soon: 'bg-muted text-muted-foreground border-border',
  urgent:
    'bg-amber-50 text-amber-700 border-amber-300/70 dark:bg-amber-900/30 dark:text-amber-300 dark:border-amber-700/50',
  today:
    'bg-amber-100 text-amber-800 border-amber-300 dark:bg-amber-900/50 dark:text-amber-200 dark:border-amber-700/60',
};

const DOT: Record<TrialUrgency, string> = {
  calm: 'bg-muted-foreground/40',
  soon: 'bg-amber-400',
  urgent: 'bg-amber-500',
  today: 'bg-amber-500',
};

export function TrialCountdown({
  daysLeft,
  size = 'sm',
}: {
  daysLeft: number;
  size?: 'sm' | 'md';
}) {
  const u = trialUrgency(daysLeft);
  const label =
    u === 'today' ? 'Ends today' : daysLeft === 1 ? '1 day left' : `${daysLeft} days left`;
  const px = size === 'md' ? 'px-2 py-1 text-[11.5px]' : 'px-1.5 py-0.5 text-[10.5px]';
  const pulse = u === 'urgent' || u === 'today' ? 'animate-pulse' : '';
  return (
    <span
      className={`inline-flex items-center gap-1.5 whitespace-nowrap rounded-full border font-medium tabular-nums ${TONE[u]} ${px}`}
    >
      <span className={`size-1.5 rounded-full ${DOT[u]} ${pulse}`} />
      {label}
    </span>
  );
}
