// Data layer for the Settings → Account card (auth-adaptive redesign).
//
// One query (GET /user, shared 'viewer' cache) + the stored credential's
// method derive a single `status` the card switches on. PAT and GitHub App
// differ only in the method-specific zone; everything above the hairline is
// shared identity. Errors are surfaced IN the card (rejected vs unreachable)
// rather than auto-bouncing to /welcome — the card owns the recover affordance.

import { useQuery } from '@tanstack/react-query';
import { getViewer, GitHubError } from '../../../github/client';
import { getCredential, type AuthMethod } from '../../../auth/tokenStore';
import type { Viewer } from '../../../github/types';

export type AccountStatus = 'pat' | 'app' | 'loading' | 'error';
export type AccountErrorKind = 'rejected' | 'fetch-failed';

export interface AccountState {
  status: AccountStatus;
  method: AuthMethod;
  viewer: Viewer | undefined;
  /** Only meaningful when status === 'error'. */
  errorKind: AccountErrorKind;
  refetch: () => void;
}

export function useAccount(): AccountState {
  const viewerQuery = useQuery<Viewer>({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    staleTime: 5 * 60_000,
  });
  const method = getCredential()?.method ?? 'github-app';

  // 401 = GitHub rejected the token (revoked/expired). Anything else from the
  // query (network drop, 5xx, status 0) reads as "couldn't reach GitHub".
  const errorKind: AccountErrorKind =
    viewerQuery.error instanceof GitHubError && viewerQuery.error.status === 401
      ? 'rejected'
      : 'fetch-failed';

  const status = deriveStatus(viewerQuery.isError, viewerQuery.data, method);

  return {
    status,
    method,
    viewer: viewerQuery.data,
    errorKind,
    refetch: () => void viewerQuery.refetch(),
  };
}

function deriveStatus(
  isError: boolean,
  data: Viewer | undefined,
  method: AuthMethod,
): AccountStatus {
  if (isError) return 'error';
  if (!data) return 'loading';
  return method === 'github-app' ? 'app' : 'pat';
}
