// Settings · AI assistance (ADR 0026 / design spec). Off by default; the
// rest of the card dims until the master toggle is on, and turning it on the
// first time requires the disclosure ack. Satisfies the settings-ai* artboards
// (settings-ai, -off, -disclosure, -nokey, -invalid, -advanced, -preview).

import { useState } from 'react';
import { ChevronDown, ChevronRight, ShieldCheck } from 'lucide-react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { Collapse } from '@/components/ui/collapse';
import { Input } from '@/components/ui/input';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { cn } from '@/lib/utils';
import { AiMark } from '../aikit';
import { useAiSettings } from './useAiSettings';
import { AiProviderKeyRow } from './AiProviderKeyRow';
import { AiProviderSetupGuide } from './AiProviderSetupGuide';
import { AiDisclosureDialog } from './AiDisclosureDialog';
import { AiGuidelinesEditor } from './AiGuidelinesEditor';
import { AiModelSelect } from './AiModelSelect';

export function AiSettingsSection() {
  const { settings, setSettings, bothKeys } = useAiSettings();
  const [disclosure, setDisclosure] = useState<null | 'enable' | 'info'>(null);
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const enabled = settings.enabled;

  function onToggle(next: boolean) {
    if (next) {
      // First enable (or any enable without a prior ack) requires the ack.
      if (!settings.disclosureAcked) {
        setDisclosure('enable');
        return;
      }
      setSettings({ enabled: true });
    } else {
      setSettings({ enabled: false });
    }
  }

  return (
    <section id="ai-assistance" className="mb-6">
      {/* Heading */}
      <div className="mb-3">
        <div className="flex items-center gap-2">
          <AiMark className="size-5 text-violet-600" />
          <h2 className="text-[17px] font-semibold tracking-tight text-foreground">AI assistance</h2>
          <span className="rounded bg-violet-100 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-violet-600">
            Opt-in
          </span>
        </div>
        <p className="mt-1 text-[13px] text-muted-foreground">
          Optional, bring-your-own-key help. Sits next to Privacy because it's the one feature that
          sends code off your machine. Every AI action is triggered by you — never automatic.
        </p>
      </div>

      {/* 1 · Enable */}
      <Card className="mb-[22px]">
        <div className="flex items-center gap-3 p-4">
          <div className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-violet-100 text-violet-600">
            <AiMark className="size-5" />
          </div>
          <div className="min-w-0 flex-1">
            <div className="text-[14px] font-semibold text-foreground">Enable AI assistance</div>
            <div className="text-[12px] text-muted-foreground">
              {enabled
                ? 'On — AI grouping and inline hints are available in PR review.'
                : 'Off by default. Turning on shows a one-time disclosure of what AI can see.'}
            </div>
          </div>
          <Switch checked={enabled} onCheckedChange={onToggle} aria-label="Enable AI assistance" />
        </div>
      </Card>

      {/* Everything below dims when AI is off */}
      <div className={enabled ? '' : 'pointer-events-none select-none opacity-50'}>
        {/* 2 · Provider keys */}
        <Card className="mb-[22px]">
          <CardHeader>
            <CardTitle>Provider keys</CardTitle>
            <CardDescription>
              Your keys, your spend. Kept in your system keychain (desktop) or this browser (web) —
              never the synced preferences file. Configure one or both.
            </CardDescription>
          </CardHeader>
          <CardContent className="p-0">
            <div className="border-t border-border/60">
              <AiProviderKeyRow provider="anthropic" model={settings.anthropicModel} />
              <AiProviderKeyRow
                provider="openai"
                model={settings.openaiModel}
                baseUrl={settings.openaiBaseUrl}
                last
              />
            </div>

            {/* 3 · Active provider — only when both keys set */}
            {bothKeys && (
              <div className="flex items-center gap-3 border-t border-border/60 px-5 py-3.5">
                <div className="flex-1">
                  <div className="text-[13px] font-medium text-foreground">Active provider</div>
                  <div className="text-[11.5px] text-muted-foreground">
                    Which configured provider the features use.
                  </div>
                </div>
                <Tabs
                  value={settings.activeProvider}
                  onValueChange={(v) =>
                    setSettings({ activeProvider: v as 'anthropic' | 'openai' })
                  }
                >
                  <TabsList indicator="pill" className="h-7">
                    <TabsTrigger
                      value="anthropic"
                      className="h-6 text-[11.5px] data-[state=active]:bg-transparent data-[state=active]:shadow-none"
                    >
                      Anthropic
                    </TabsTrigger>
                    <TabsTrigger
                      value="openai"
                      className="h-6 text-[11.5px] data-[state=active]:bg-transparent data-[state=active]:shadow-none"
                    >
                      OpenAI
                    </TabsTrigger>
                  </TabsList>
                </Tabs>
              </div>
            )}

            {/* 4 · Advanced model override */}
            <div className="border-t border-border/60">
              <button
                type="button"
                onClick={() => setAdvancedOpen((o) => !o)}
                className="flex w-full items-center gap-2 px-5 py-2.5 text-left"
              >
                {advancedOpen ? (
                  <ChevronDown className="size-3.5 text-muted-foreground" />
                ) : (
                  <ChevronRight className="size-3.5 text-muted-foreground" />
                )}
                <span className="text-[12.5px] font-medium text-foreground">Advanced</span>
                <span className="text-[11.5px] text-muted-foreground">Model override · optional</span>
              </button>
              <Collapse open={advancedOpen} className="space-y-3 px-5 pb-3 pl-11">
                  <div className="flex items-center gap-3">
                    <span className="w-24 shrink-0 text-[12px] text-muted-foreground">Anthropic</span>
                    <AiModelSelect
                      provider="anthropic"
                      value={settings.anthropicModel}
                      onChange={(v) => setSettings({ anthropicModel: v })}
                    />
                  </div>
                  <div className="flex items-center gap-3">
                    <span className="w-24 shrink-0 text-[12px] text-muted-foreground">OpenAI</span>
                    {settings.openaiBaseUrl ? (
                      <Input
                        value={settings.openaiModel}
                        onChange={(e) => setSettings({ openaiModel: e.target.value.trim() })}
                        placeholder="e.g. llama-3.3-70b-versatile"
                        className="h-8 text-[12.5px]"
                      />
                    ) : (
                      <AiModelSelect
                        provider="openai"
                        value={settings.openaiModel}
                        onChange={(v) => setSettings({ openaiModel: v })}
                      />
                    )}
                  </div>
                  <p className="text-[11px] leading-snug text-muted-foreground">
                    A short curated list per provider, populated from the provider’s current models —
                    pick a faster or stronger one. Leave on Default unless you have a reason.
                  </p>

                  {/* OpenAI-compatible base URL — point OpenAI at Groq, Gemini,
                      a local Ollama, etc. (handy for free testing). */}
                  <div className="flex items-center gap-3 border-t border-border/60 pt-3">
                    <span className="w-24 shrink-0 text-[12px] text-muted-foreground">
                      OpenAI URL
                    </span>
                    <Input
                      value={settings.openaiBaseUrl}
                      onChange={(e) => setSettings({ openaiBaseUrl: e.target.value.trim() })}
                      placeholder="https://api.openai.com/v1 (default)"
                      className="h-8 font-mono text-[12px]"
                    />
                  </div>
                  <p className="text-[11px] leading-snug text-muted-foreground">
                    Override to any OpenAI-compatible endpoint — Groq
                    (<code className="ai-code">https://api.groq.com/openai/v1</code>), Gemini, or a
                    local Ollama (<code className="ai-code">http://localhost:11434/v1</code>) — then set
                    the exact model id above. Include the version path. Structured-output support
                    varies by endpoint; Pyor falls back to JSON-object mode when strict schemas
                    aren’t supported.
                  </p>
              </Collapse>
            </div>

            {/* 5 · Connect a provider — step-by-step setup (Ollama / Groq /
                Gemini / OpenRouter / OpenAI / Anthropic). */}
            <AiProviderSetupGuide settings={settings} onApply={(patch) => setSettings(patch)} />
          </CardContent>
        </Card>

        {/* 6 · Review guidelines */}
        <div className="mb-4">
          <div className="mb-2 flex items-baseline gap-2">
            <h3 className="text-[15px] font-semibold tracking-tight text-foreground">
              Add your review preferences
            </h3>
            <span className="text-[12px] text-muted-foreground">
              Optional — layered on top of Pyor's built-in reviewer.
            </span>
          </div>
          <AiGuidelinesEditor
            value={settings.guidelines}
            onSave={(g) => setSettings({ guidelines: g })}
          />
        </div>

        {/* 7 · What AI can see */}
        <button
          type="button"
          onClick={() => setDisclosure('info')}
          className="inline-flex items-center gap-1.5 text-[12px] text-muted-foreground hover:text-violet-700"
        >
          <ShieldCheck className="size-3.5" />
          What AI can see{' '}
          <span className="text-muted-foreground">· diff + changed files, only when you trigger a run</span>
        </button>
      </div>

      <AiDisclosureDialog
        open={disclosure !== null}
        mode={disclosure === 'info' ? 'info' : 'enable'}
        onOpenChange={(o) => {
          if (!o) setDisclosure(null);
        }}
        onConfirm={() => {
          setSettings({ enabled: true, disclosureAcked: true });
          setDisclosure(null);
        }}
      />
    </section>
  );
}
