// The provider catalog behind AiProviderSetupGuide — declarative content
// (commands, URLs, models, one-click presets) for every supported backend.
// All the OpenAI-compatible ones (Ollama / Groq / Gemini / OpenRouter) ride
// the single adapter PR #265 added, so each is just data here, no new code.
// Kept separate from the component so the steps stay easy to edit and the
// component proper stays small.

import { useState } from 'react';
import { ExternalLink } from 'lucide-react';
import { CopyIconMorph } from '@/components/ui/copy-icon';
import { cn } from '@/lib/utils';
import ollamaSvg from '@lobehub/icons-static-svg/icons/ollama.svg?raw';
import groqSvg from '@lobehub/icons-static-svg/icons/groq.svg?raw';
import geminiColorSvg from '@lobehub/icons-static-svg/icons/gemini-color.svg?raw';
import openrouterSvg from '@lobehub/icons-static-svg/icons/openrouter.svg?raw';
import openaiSvg from '@lobehub/icons-static-svg/icons/openai.svg?raw';
import anthropicSvg from '@lobehub/icons-static-svg/icons/anthropic.svg?raw';
import type { AiSettings } from './aiSettings';

// Provider brand marks from @lobehub/icons-static-svg. No svgr plugin in vite,
// so imported as raw strings + inlined — inlining keeps `fill="currentColor"`
// live (an <img> would render it opaque) and lets us paint each in its brand
// color. Keyed by guide id.
//
// Color strategy (preserve each brand's identity):
//   · Gemini ships as multi-stop gradient art → use the -color SVG as-is.
//   · Groq (orange) + Anthropic/Claude (coral) are mono marks with a known
//     brand hue → tint via BRAND_COLOR (CSS color drives `currentColor`).
//   · OpenAI / Ollama / OpenRouter are monochrome brands (black ⇄ white) →
//     no tint, so they inherit text color and stay visible in both themes.
const PROVIDER_SVG: Record<string, string> = {
  ollama: ollamaSvg,
  groq: groqSvg,
  gemini: geminiColorSvg,
  openrouter: openrouterSvg,
  openai: openaiSvg,
  anthropic: anthropicSvg,
};

const BRAND_COLOR: Record<string, string | undefined> = {
  groq: '#F55036',
  anthropic: '#D97757',
};

export function ProviderIcon({ id, className }: { id: string; className?: string }) {
  const svg = PROVIDER_SVG[id];
  if (!svg) return null;
  const color = BRAND_COLOR[id];
  return (
    <span
      aria-hidden
      className={cn('inline-flex shrink-0 [&>svg]:size-full', className)}
      style={color ? { color } : undefined}
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}

export type Tone = 'free' | 'local' | 'paid';
export type Preset = Partial<AiSettings>;
export type Guide = {
  id: string;
  name: string;
  badge: { label: string; tone: Tone };
  blurb: string;
  steps: React.ReactNode[];
  preset?: Preset;
  applyLabel?: string;
  keyHint?: React.ReactNode;
};

// A copy-on-click monospace chip (reuses the violet `.ai-code` treatment).
export function Copyable({ value, display }: { value: string; display?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      title="Copy"
      onClick={async () => {
        await navigator.clipboard.writeText(value);
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
      }}
      className="ai-code inline-flex items-center gap-1 align-baseline transition-[filter] hover:brightness-110"
    >
      <span className="select-none">{display ?? value}</span>
      <CopyIconMorph copied={copied} className="size-3 opacity-60" />
    </button>
  );
}

function Ext({ href, children }: { href: string; children: React.ReactNode }) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noreferrer"
      className="inline-flex items-center gap-0.5 font-medium text-violet-700 underline-offset-2 hover:underline dark:text-violet-300"
    >
      {children}
      <ExternalLink className="size-3" />
    </a>
  );
}

export function matchesPreset(s: AiSettings, p: Preset): boolean {
  return Object.entries(p).every(([k, v]) => s[k as keyof AiSettings] === v);
}

