// OAuth scopes as wrapping monospace code chips (PAT mode only). Neutral
// surface — the green accent is reserved for the App method, so scopes stay
// quiet and scannable even at 8+. Zero scopes → a dashed empty state rather
// than a blank gap.

import { Ban } from 'lucide-react';

export function ScopePills({ scopes }: { scopes: string[] }) {
  if (scopes.length === 0) {
    return (
      <div className="inline-flex items-center gap-2 rounded-md border border-dashed border-border bg-muted/40 px-2.5 py-1.5 text-[12px] text-muted-foreground">
        <Ban className="size-3.5" />
        No scopes granted
      </div>
    );
  }
  return (
    <div className="flex flex-wrap gap-1.5">
      {scopes.map((s) => (
        <code
          key={s}
          className="rounded-md border border-border/60 bg-muted px-1.5 py-1 font-mono text-[11.5px] leading-none text-foreground"
        >
          {s}
        </code>
      ))}
    </div>
  );
}
