// Seat-panel data (ADR 0020 #7): the claimant list + revoke that Polar can't
// show (Polar owns quantity N + invoices; OUR backend owns who occupies the N
// seats). Backed by the admin-gated GET /billing/seats + POST
// /billing/seats/revoke endpoints. No-ops cleanly when no broker is wired (mock
// / unprovisioned) — the panel falls back to the seat counts in the entitlement.

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getToken } from '../auth/tokenStore';

const BROKER_URL = (
  import.meta.env.VITE_AUTH_BROKER_URL as string | undefined
)?.trim();

export interface SeatClaimant {
  seatId: number;
  login: string;
  identityId: number | null;
  claimedAt: number | null;
  index: number;
  total: number;
}

async function fetchSeats(githubOrgId: number): Promise<SeatClaimant[]> {
  const token = getToken();
  const res = await fetch(
    `${BROKER_URL}/billing/seats?githubOrgId=${githubOrgId}`,
    { headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}) } },
  );
  if (!res.ok) throw new Error('seats_read_failed');
  const data = (await res.json()) as { claimants?: SeatClaimant[] };
  return data.claimants ?? [];
}

/** Claimant list for an org's seats (admin-only; enable only for admins). */
export function useSeatClaimants(githubOrgId: number, enabled: boolean) {
  return useQuery({
    queryKey: ['seats', githubOrgId],
    queryFn: () => fetchSeats(githubOrgId),
    enabled: enabled && !!BROKER_URL,
    staleTime: 30_000,
  });
}

/** Revoke a seat; refreshes the claimant list + entitlement on success. */
export function useRevokeSeat(githubOrgId: number) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (seatId: number) => {
      const token = getToken();
      const res = await fetch(`${BROKER_URL}/billing/seats/revoke`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({ githubOrgId, seatId }),
      });
      if (!res.ok) throw new Error('revoke_failed');
      return (await res.json()) as { revoked: boolean };
    },
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: ['seats', githubOrgId] });
      void qc.invalidateQueries({ queryKey: ['entitlement'] });
    },
  });
}

/** Whether a backend is wired (claimant list / revoke require it). */
const hasBillingBackend = !!BROKER_URL;
