// Settings · AI assistance — "Connect a provider" step-by-step guide.
// A collapsible teaching surface under the provider-key rows: pick a
// provider tab (local Ollama · free Groq/Gemini · OpenRouter · the paid
// first-parties) and get copy-paste-able commands, URLs, and a one-click
// "Apply these settings" that fills the OpenAI-compatible base URL + model
// for you. Content lives in ./aiProviderGuides; this file is just the chrome.

import { useState } from 'react';
import { Check, ChevronDown, ChevronRight } from 'lucide-react';
import { Collapse } from '@/components/ui/collapse';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { cn } from '@/lib/utils';
import { AiButton } from '../aikit';
import type { AiSettings } from './aiSettings';
import { AI_PROVIDER_GUIDES, ProviderIcon, matchesPreset, type Preset, type Tone } from './aiProviderGuides';

function Badge({ tone, children }: { tone: Tone; children: React.ReactNode }) {
  const tones: Record<Tone, string> = {
    free: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300',
    local: 'bg-violet-100 text-violet-700 dark:bg-violet-500/15 dark:text-violet-300',
    paid: 'bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300',
  };
  return (
    <span className={cn('rounded px-1.5 py-px text-[10px] font-semibold uppercase tracking-wide', tones[tone])}>
      {children}
    </span>
  );
}

export function AiProviderSetupGuide({
  settings,
  onApply,
}: {
  settings: AiSettings;
  onApply: (patch: Preset) => void;
}) {
  const [open, setOpen] = useState(false);
  const [activeId, setActiveId] = useState(AI_PROVIDER_GUIDES[0].id);
  const guide = AI_PROVIDER_GUIDES.find((g) => g.id === activeId) ?? AI_PROVIDER_GUIDES[0];
  const isActive = guide.preset ? matchesPreset(settings, guide.preset) : false;

  return (
    <div className="border-t border-border/60">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="flex w-full items-center gap-2 px-5 py-2.5 text-left"
      >
        {open ? (
          <ChevronDown className="size-3.5 text-muted-foreground" />
        ) : (
          <ChevronRight className="size-3.5 text-muted-foreground" />
        )}
        <span className="text-[12.5px] font-medium text-foreground">Connect a provider</span>
        <span className="text-[11.5px] text-muted-foreground">Step-by-step · free options included</span>
      </button>

      <Collapse open={open} className="px-5 pb-4 pl-11">
        {/* Provider switcher — shared segmented Tabs (same primitive + animated
            pill indicator as the Changes-toolbar diff-mode switcher). */}
        <Tabs value={activeId} onValueChange={setActiveId}>
          <TabsList indicator="pill" className="h-auto flex-wrap justify-start gap-0.5">
            {AI_PROVIDER_GUIDES.map((g) => (
              <TabsTrigger
                key={g.id}
                value={g.id}
                className="h-7 gap-1.5 px-2.5 text-[12px] data-[state=active]:bg-transparent data-[state=active]:shadow-none"
              >
                <ProviderIcon id={g.id} className="size-3.5" />
                {g.name}
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>

        {/* Active provider panel */}
        <div className="mt-3 rounded-lg border border-violet-200/70 bg-violet-50/40 p-3.5 dark:border-violet-500/20 dark:bg-violet-500/[0.06]">
          <div className="flex items-center gap-2">
            <div className="flex size-7 shrink-0 items-center justify-center rounded-lg bg-violet-100 text-violet-600 dark:bg-violet-500/20 dark:text-violet-300">
              <ProviderIcon id={guide.id} className="size-4" />
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-2">
                <span className="text-[13.5px] font-semibold text-foreground">{guide.name}</span>
                <Badge tone={guide.badge.tone}>{guide.badge.label}</Badge>
              </div>
              <div className="text-[11.5px] leading-snug text-muted-foreground">{guide.blurb}</div>
            </div>
          </div>

          <ol className="mt-3 space-y-2.5">
            {guide.steps.map((body, i) => (
              <li key={i} className="flex gap-2.5">
                <span className="mt-px flex size-5 shrink-0 items-center justify-center rounded-full bg-violet-100 text-[11px] font-semibold text-violet-700 dark:bg-violet-500/20 dark:text-violet-300">
                  {i + 1}
                </span>
                <div className="text-[12.5px] leading-relaxed text-foreground/90">{body}</div>
              </li>
            ))}
          </ol>

          {guide.preset && (
            <div className="mt-3 flex flex-wrap items-center gap-x-2.5 gap-y-1 border-t border-violet-200/60 pt-3 dark:border-violet-500/15">
              <AiButton variant="solid" size="sm" onClick={() => onApply(guide.preset!)}>
                {isActive ? 'Re-apply' : (guide.applyLabel ?? 'Apply these settings')}
              </AiButton>
              {isActive && (
                <span className="inline-flex items-center gap-1 text-[11.5px] font-medium text-emerald-600 dark:text-emerald-400">
                  <Check className="size-3.5" />
                  Currently set
                </span>
              )}
              {guide.keyHint && <span className="text-[11px] text-muted-foreground">{guide.keyHint}</span>}
            </div>
          )}
        </div>
      </Collapse>
    </div>
  );
}
